{
  "scenario_title": "Weekly serious adverse event reporting volume and latency across Phase III trial arms in 2023",
  "data_context": "The pharmacovigilance safety operations team tracked individual serious adverse event (SAE) expedited reports across multinational clinical sites in 2023 to monitor regulatory reporting timeliness and case complexity across active oncology treatment arms.",
  "script": "dim(\"trial_arm\", [\"Monotherapy High-Dose\", \"Monotherapy Low-Dose\", \"Active Comparator\"], weights=[0.45, 0.35, 0.20], group=\"cohort\")\ndim(\"seriousness_tier\", [\"Fatal / Life-Threatening\", \"Hospitalization\", \"Significant Disability\"], weights=[0.20, 0.65, 0.15], ordered=\"ordinal\", group=\"clinical_impact\")\ndim(\"event_category\", [\"Hematologic\", \"Gastrointestinal\", \"Infection\", \"Cardiovascular\"], weights=[0.35, 0.30, 0.20, 0.15], group=\"medra_system\")\n\ntime(\"report_week\", start=\"2023-01-02\", end=\"2023-12-25\", freq=\"weekly\")\n\nmeasure(\"reporting_latency_days\", \"lognormal(mu = 1.6 - 0.4*[seriousness_tier=Fatal / Life-Threatening] + 0.2*[event_category=Cardiovascular], sigma = 0.30)\", unit=\"days\", additive=True)\nmeasure(\"query_count\", \"poisson(lam = 1.2 + 0.6*[seriousness_tier=Fatal / Life-Threatening] + 0.3*[trial_arm=Monotherapy High-Dose])\", unit=\"queries\", additive=True)\nmeasure(\"safety_review_hours\", \"lognormal(mu = 1.8 + 0.25*query_count + 0.20*[seriousness_tier=Fatal / Life-Threatening], sigma = 0.20)\", unit=\"hours\", additive=True)\n\nemit(360)",
  "intents": [
    {
      "sentence": "Compare average reporting latency across seriousness severity tiers",
      "columns": [
        "seriousness_tier",
        "reporting_latency_days"
      ],
      "aggregate": "AVG",
      "family": "comparison"
    },
    {
      "sentence": "Track mean weekly reporting latency over the 2023 trial period",
      "columns": [
        "report_week",
        "reporting_latency_days"
      ],
      "aggregate": "AVG",
      "family": "trend"
    },
    {
      "sentence": "Assess the relationship between site query counts and safety review workload hours",
      "columns": [
        "query_count",
        "safety_review_hours"
      ],
      "aggregate": "NONE",
      "family": "relation"
    },
    {
      "sentence": "Analyze the distribution of reported medical event categories across trial arms",
      "columns": [
        "trial_arm",
        "event_category"
      ],
      "aggregate": "COUNT",
      "family": "composition"
    }
  ]
}
